-- Deletes revisions that no loot links and that repeat every attribute of a
-- linked revision: NPC revisions of LOO-34..LOO-250 that differed from their
-- edition revision only in the world dropped by LOO-252, and item revisions
-- LOO-250-prod-1 retired into a promoted one. The repair moved all their
-- loots, their hashes are pre-edition or null so no writer can match them
-- again, and the linked twin keeps every value they held.
DELETE FROM "NpcSnapshot" WHERE NOT EXISTS (SELECT 1 FROM "LootNpc" WHERE "LootNpc"."npcSnapshotId" = "NpcSnapshot"."id") AND EXISTS (SELECT 1 FROM "NpcSnapshot" AS "linked" WHERE "linked"."id" <> "NpcSnapshot"."id" AND "linked"."npcId" = "NpcSnapshot"."npcId" AND "linked"."identityNamespace" = "NpcSnapshot"."identityNamespace" AND "linked"."gameVersion" = "NpcSnapshot"."gameVersion" AND "linked"."name" = "NpcSnapshot"."name" AND "linked"."type" IS NOT DISTINCT FROM "NpcSnapshot"."type" AND "linked"."lvl" IS NOT DISTINCT FROM "NpcSnapshot"."lvl" AND "linked"."icon" IS NOT DISTINCT FROM "NpcSnapshot"."icon" AND "linked"."wt" IS NOT DISTINCT FROM "NpcSnapshot"."wt" AND "linked"."margonemType" IS NOT DISTINCT FROM "NpcSnapshot"."margonemType" AND "linked"."prof" IS NOT DISTINCT FROM "NpcSnapshot"."prof" AND EXISTS (SELECT 1 FROM "LootNpc" WHERE "LootNpc"."npcSnapshotId" = "linked"."id"));--> statement-breakpoint
DELETE FROM "ItemSnapshot" WHERE NOT EXISTS (SELECT 1 FROM "LootItem" WHERE "LootItem"."itemSnapshotId" = "ItemSnapshot"."id") AND EXISTS (SELECT 1 FROM "ItemSnapshot" AS "linked" WHERE "linked"."id" <> "ItemSnapshot"."id" AND "linked"."itemId" = "ItemSnapshot"."itemId" AND "linked"."gameVersion" = "ItemSnapshot"."gameVersion" AND "linked"."statsHash" = "ItemSnapshot"."statsHash" AND "linked"."name" = "ItemSnapshot"."name" AND "linked"."icon" = "ItemSnapshot"."icon" AND "linked"."itemType" IS NOT DISTINCT FROM "ItemSnapshot"."itemType" AND EXISTS (SELECT 1 FROM "LootItem" WHERE "LootItem"."itemSnapshotId" = "linked"."id"));
